def max_non_overlapping(intervals):
    intervals = sorted(intervals, key=lambda item: item[1])
    count = 0
    end = float("-inf")
    for start, finish in intervals:
        if start >= end:
            count += 1
            end = finish
    return count

print(max_non_overlapping([(1,3),(2,4),(3,5),(6,8)]))

