        seen[n]=i

def valid(s):
    st=[];pairs={')':'(',']':'[','}':'{'}
    for c in s:
        if c in pairs:
            if not st or st.pop()!=pairs[c]: return False
        else: st.append(c)
    return not st

def longest(s):
    seen={};l=0;best=0
    for r,c in enumerate(s):
        if c in seen and seen[c]>=l: l=seen[c]+1
        seen[c]=r; best=max(best,r-l+1)
    return best
